"""Verify synthetic PDFs generated by tests/pdf-output.test.mts (requires PyMuPDF)."""
import collections
import pathlib
import re
import sys
import fitz

root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else '/tmp/pdfs/hospital-v1')
for name in ['invoice.pdf', 'voided-invoice.pdf', 'prescription.pdf']:
    document = fitz.open(root / name)
    pages = [page.get_text() for page in document]
    text = '\n'.join(pages)
    assert document.page_count >= 1, name
    assert not any(ord(char) < 32 and char not in '\n\r\t' for char in text), f'{name}: unsupported glyph'
    for number, page in enumerate(document, 1):
        assert f'Page {number} of {len(pages)}' in pages[number - 1], f'{name}: page reference missing'
        for word in page.get_text('words'):
            assert word[0] >= 15 and word[1] >= 15 and word[2] <= page.rect.width - 15 and word[3] <= page.rect.height - 10, f'{name}: text exceeds page bounds'
        page.get_pixmap(matrix=fitz.Matrix(1.25, 1.25)).save(root / f'{pathlib.Path(name).stem}-{number}.png')
    if name.endswith('invoice.pdf'):
        assert 'PKR' in text and '$' not in text, f'{name}: configured currency not used'
    if name == 'voided-invoice.pdf':
        assert all('VOIDED' in page for page in pages), 'Every voided invoice page must be marked'
        assert 'Remaining' in text and 'PKR 0.00' in text
    if name == 'prescription.pdf':
        assert 'Rx' in text and len(pages) >= 2
        medicines = [int(n) for n in re.findall(r'Synthetic medicine\s+(\d+)\b', text)]
        assert collections.Counter(medicines) == collections.Counter(range(1, 21)), 'Missing or duplicated medicine'
        for page in pages:
            normalized = re.sub(r'\s+', ' ', page)
            rows = len(re.findall(r'Synthetic medicine\s+\d+\b', page))
            instructions = normalized.count('Synthetic medicine instruction')
            assert rows == instructions, 'A medicine row split across pages'
            assert 'pdf-' in page, 'Patient reference missing on a continuation page'
    print(f'PASS {name}: {len(pages)} page(s), text/bounds/continuation checks; PNGs rendered')
